CREATE TABLE IF NOT EXISTS tenant_settings(tenant_id TEXT PRIMARY KEY,display_name TEXT NOT NULL,status TEXT NOT NULL,data_region TEXT NOT NULL,default_sensitivity TEXT NOT NULL,quota_profile TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS break_glass_requests(request_id TEXT PRIMARY KEY,actor_subject TEXT NOT NULL,reason TEXT NOT NULL,expires_at TEXT NOT NULL,approved_by TEXT,created_at TEXT NOT NULL);